def max_sub_array_sum_repeated(a, n, k):
    """Write a function to find the largest sum of contiguous array in the modified array which is formed by repeating the given array k times."""
    if n is None or k is None:
        return 0
    if n <= 0 or k <= 0:
        return 0
    if not a:
        return 0
    arr = list(a[:n])
    if not arr:
        return 0
    # Kadane on single copy (non-empty subarray).
    max_ending = arr[0]
    max_single = arr[0]
    for x in arr[1:]:
        if x > max_ending + x:
            max_ending = x
        else:
            max_ending = max_ending + x
        if max_ending > max_single:
            max_single = max_ending
    if k == 1:
        return max_single
    total = sum(arr)
    # Max prefix sum.
    cur = arr[0]
    max_prefix = cur
    for x in arr[1:]:
        cur += x
        if cur > max_prefix:
            max_prefix = cur
    # Max suffix sum.
    cur = arr[-1]
    max_suffix = cur
    for x in reversed(arr[:-1]):
        cur += x
        if cur > max_suffix:
            max_suffix = cur
    if total > 0:
        candidate = max_prefix + max_suffix + (k - 2) * total
    else:
        candidate = max_prefix + max_suffix
    if max_single > candidate:
        return max_single
    return candidate
